// Campus scene file format (generated by deploy/engine-scene.mjs into
// public/engine/campus-2026.json) and the provenance-tagged runtime types.
import type { Confidence, Provenance, Region } from '../world/types.ts';
import type { Obstacle, SpatialScene, Surface } from '../spatial/types.ts';

export const CAMPUS_SCENE_SCHEMA = 'mars-campus-scene/1';

export type ObstacleKind = NonNullable<Obstacle['kind']>;

/**
 * Compact obstacle row:
 * [id, kind, cx, cz, hx, hz, yaw, y0, y1, label index, confidence, assembly, component id]
 * `component` is the manifest component_id (ids with suffixes are parts of it).
 */
export type ObstacleRow = [string, ObstacleKind, number, number, number, number, number, number, number, number, Confidence, string, string];

export type CampusSceneFile = {
  schema: typeof CAMPUS_SCENE_SCHEMA;
  campus: 'mars-2026';
  generator: string;
  source: { glb: string; glbBytes: number; manifest: string; status: string };
  groundY: number;
  /** Site bearing of this scene's frame (degrees; engine/env/sun.ts NORTH_AZIMUTH_OFFSET convention). Absent = the
   *  global; present only where a year was measured (YEAR_NORTH_AZIMUTH_OFFSET). Additive (W51). */
  northAzimuthOffset?: number;
  bands: { low: [number, number]; note: string };
  bounds: [number, number, number, number];
  assemblies: { id: string; name: string }[];
  labels: string[];
  obstacles: ObstacleRow[];
  /** Named regions (assemblies + hypothetical flagship areas), with provenance. */
  regions: Region[];
  stats: Record<string, number>;
  /** hashOf(everything except contentHash) — extraction determinism check. */
  contentHash: string;
};

/** An obstacle with its manifest identity and epistemic status. Structurally an `Obstacle`. */
export type CampusObstacle = Obstacle & {
  component: string;
  assembly: string;
  provenance: Provenance;
};

export type CampusSurface = Surface & { provenance: Provenance; walkableReason: string };

export type CampusScene = Omit<SpatialScene, 'obstacles' | 'surfaces'> & {
  obstacles: CampusObstacle[];
  surfaces: CampusSurface[];
  regions: Region[];
  meta: { groundY: number; contentHash: string; source: CampusSceneFile['source']; notes: string[]; northAzimuthOffset?: number };
};
